def data(n: int, p: int, nc: int):
    X = np.zeros((n, p)); y = np.zeros(n, dtype=int)
    for i in range(n):
        y[i] = i % nc
        for j in range(p):
            v = (i * 7919 + j * 104729 + i * j * 13 + j * j * 3) % 101
            X[i, j] = (v - 50.0) / 25.0 + (0.8 * y[i] if (j + y[i]) % 2 == 0 else -0.3 * y[i])
    return X, y

def signals(n_trials: int, n_ch: int, n_t: int):
    X = np.zeros((n_trials, n_ch, n_t)); y = np.zeros(n_trials, dtype=int)
    for i in range(n_trials):
        y[i] = i % 2
        for c in range(n_ch):
            for t in range(n_t):
                v = (i * 1009 + c * 7919 + t * 104729 + i * c * t * 13 + t * t * (c + 1) * 3 + c * c * t * 7) % 101
                X[i, c, t] = (v - 50.0) / 25.0 + ((0.9 * y[i]) if (c + t) % 3 == 0 else 0.0) * (1 + c % 2)
    return X, y

def close(got, exp: List[float], rtol: float, atol: float = 1e-12) -> bool:
    g = np.asarray(got, dtype=float).ravel()
    if g.size != len(exp):
        print("size mismatch", g.size, len(exp))
        return False
    for i in range(len(exp)):
        if abs(g[i] - exp[i]) > atol + rtol * abs(exp[i]):
            print("mismatch at", i, g[i], exp[i])
            return False
    return True

