@test
def t_covariance():
    X, y = data(60, 5, 3)
    e = EmpiricalCovariance().fit(X)
    assert close(e.covariance_, cov_emp, 1e-12) and close(e.precision_, prec_emp, 1e-10)
    assert close(e.mahalanobis(X[:5]), maha_emp, 1e-10) and close([e.score(X[:20])], [score_emp], 1e-10)
    l = LedoitWolf().fit(X)
    assert close(l.covariance_, cov_lw, 1e-12) and close(l.precision_, prec_lw, 1e-10)
    assert close([l.shrinkage_], [sh_lw], 1e-12) and close(l.mahalanobis(X[:5]), maha_lw, 1e-10)
    assert close([l.score(X[:20])], [score_lw], 1e-10)
    o = OAS().fit(X)
    assert close(o.covariance_, cov_oas, 1e-12) and close(o.precision_, prec_oas, 1e-10)
    assert close([o.shrinkage_], [sh_oas], 1e-12) and close([o.score(X[:20])], [score_oas], 1e-10)
    s = ShrunkCovariance(shrinkage=0.2).fit(X)
    assert close(s.covariance_, cov_shr, 1e-12) and close(s.mahalanobis(X[:5]), maha_shr, 1e-10)
    assert close(ledoit_wolf(X[:, :3])[0], lwf, 1e-12) and close(oas(X[:, 1:])[0], oasf, 1e-12)

@test
def t_scalers():
    X, y = data(60, 5, 3)
    assert close(MinMaxScaler().fit_transform(X)[:6], mm_t, 1e-12)
    assert close(MinMaxScaler((-1.0, 2.0)).fit(X).transform(X[:4] * 1.5), mm_t2, 1e-12)
    assert close(RobustScaler().fit_transform(X)[:6], rb_t, 1e-12)
    assert close(RobustScaler().fit(X).center_, rb_c, 1e-12)
    assert close(RobustScaler(quantile_range=(10.0, 90.0), unit_variance=True).fit(X).scale_, rb_s, 1e-12)
    ft = FunctionTransformer(lambda a: np.log1p(a), lambda a: np.expm1(a))
    T = ft.fit_transform(np.abs(X[:4]))
    assert close(T, ft_t, 1e-14)
    assert close(ft.inverse_transform(T), list(np.abs(X[:4]).ravel()), 1e-12)

@test
def t_fastica():
    S = np.zeros((300, 3))
    for t in range(300):
        S[t, 0] = np.sin(t * 0.07); S[t, 1] = 1.0 if (t // 13) % 2 == 0 else -1.0; S[t, 2] = ((t * 37) % 41) / 20.5 - 1.0
    A = np.array([[1.0, 0.5, 0.3], [0.4, 1.2, 0.2], [0.3, 0.6, 0.9]])
    M = S @ A.T
    ica = FastICA(n_components=3, random_state=0, max_iter=400).fit(M)
    assert close(ica.components_, ica_comp_par, 1e-9, 1e-11) and close(ica.mixing_, ica_mix_par, 1e-9, 1e-11)
    assert ica.n_iter_ == ica_iter_par and close(ica.transform(M[:5]), ica_src_par, 1e-9, 1e-11)
    d = FastICA(n_components=3, random_state=0, max_iter=400, algorithm="deflation").fit(M)
    assert close(d.components_, ica_comp_def, 1e-9, 1e-11) and d.n_iter_ == ica_iter_def
    assert close(d.transform(M[:5]), ica_src_def, 1e-9, 1e-11)
    e = FastICA(n_components=3, random_state=0, max_iter=400, fun="exp").fit(M)
    assert close(e.components_, ica_comp_exp, 1e-9, 1e-11) and e.n_iter_ == ica_iter_exp
    c = FastICA(n_components=3, random_state=0, max_iter=400, fun="cube", whiten="arbitrary-variance").fit(M)
    assert close(c.components_, ica_comp_cube, 1e-9, 1e-11) and c.n_iter_ == ica_iter_cube
    assert close(c.mixing_, ica_mix_cube, 1e-9, 1e-11)
    h = FastICA(n_components=3, random_state=0, max_iter=400, whiten_solver="eigh").fit(M)
    assert close(h.components_, ica_comp_eigh, 1e-8, 1e-10) and h.n_iter_ == ica_iter_eigh
    i2 = FastICA(n_components=2, random_state=3).fit(M)
    assert close(i2.components_, ica2_comp, 1e-9, 1e-11)
    assert close(ica.inverse_transform(ica.transform(M)), list(M.ravel()), 1e-10, 1e-12)

@test
def t_pyriemann_pipelines():
    XS, ys = signals(24, 4, 64)
    cv = KFold(4)
    p1 = make_pipeline(Covariances("oas"), TangentSpace(metric="riemann"), LogisticRegression(max_iter=1000))
    assert close(cross_val_score(p1, XS, ys, cv=cv), pr_cvs, 1e-12)
    pp = cross_val_predict(p1, XS, ys, cv=cv)
    assert all(int(pp[i]) == pr_cvp[i] for i in range(24))
    p2 = make_pipeline(Covariances("lwf"), MDM(metric="riemann"))
    assert close(cross_val_score(p2, XS, ys, cv=cv), pr_cvs_mdm, 1e-12)
    g = GridSearchCV(make_pipeline(Covariances("scm"), TangentSpace(), SVC()), {"svc__C": [0.01, 1.0, 100.0]}, cv=cv).fit(XS, ys)
    assert close(g.cv_results_["mean_test_score"], pr_gs, 1e-12) and g.best_index_ == pr_gs_best
    lr = make_pipeline(Covariances("oas"), TangentSpace(), StandardScaler(), LogisticRegression(max_iter=1000)).fit(XS, ys)
    # near-separable: L-BFGS (tol=1e-12) stops ~1e-7 short of the optimum,
    # the Newton port reaches it; compare coefficients in absolute terms
    assert close(lr.steps[-1][1].coef_, pr_coef, 1e-6, 1e-6)
    assert close(lr.predict_proba(XS[:6]), pr_proba, 1e-6, 1e-9)

t_covariance()
t_scalers()
t_fastica()
t_pyriemann_pipelines()
